from v17_raw_lab import main_raw
main_raw(project,run_name=namespace['RAW_RUN_NAME'],config=namespace['RAW_CONFIG'],
         hours=namespace['HOURS'],prepare_only=namespace.get('PREPARE_ONLY',False))
